class IdentityWorker {
    constructor() {
        this.listeners = new Map();
        this.keys = new Set();
        this.baselineRows = 0;
        this.terminated = false;
    }
    addEventListener(type, callback) {
        this.listeners.set(type, [...(this.listeners.get(type) || []), callback]);
    }
    removeEventListener(type, callback) {
        this.listeners.set(type, (this.listeners.get(type) || []).filter(value => value !== callback));
    }
    postMessage(message) {
        queueMicrotask(() => {
            const response = { requestId: message.requestId, indexId: message.indexId, ok: true };
            if (message.op === 'identity-add') {
                response.addedBytes = 0;
                for (const key of message.keys) {
                    if (!this.keys.has(key)) {
                        this.keys.add(key);
                        response.addedBytes += key.length * 2 + 16;
                    }
                }
                this.baselineRows += message.keys.length;
                response.baselineRows = this.baselineRows;
            } else if (message.op === 'identity-filter') {
                response.unseen = message.keys.map((key, index) => this.keys.has(key) ? -1 : index)
                    .filter(index => index >= 0);
            } else if (message.op === 'identity-dispose') {
                this.keys.clear();
                response.disposed = true;
            }
            for (const listener of this.listeners.get('message') || []) listener({ data: response });
        });
    }
    terminate() { this.terminated = true; }
}

test('typed RDF identity distinguishes values and honors blank-node provenance recursively', () => {
    const { api } = loadApi();
    const key = term => api.termIdentity(term, 'server/repository');
    const iri = value => ({ kind: 'iri', value });
    const literal = (value, extras = {}) => ({ kind: 'literal', value, ...extras });
    const blank = (scope, reference = false) => ({ kind: 'bnode', value: 'same', scope, reference });
    const triple = object => ({ kind: 'triple', subject: iri('urn:s'), predicate: iri('urn:p'), object });
    const xsdString = 'http://www.w3.org/2001/XMLSchema#string';
    const rdfLangString = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#langString';
    const rdfDirLangString = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#dirLangString';

    assert.notEqual(key(iri('same')), key(literal('same')));
    assert.equal(key(literal('same')), key(literal('same', { datatype: xsdString })));
    assert.notEqual(key(literal('same', { datatype: 'urn:a' })), key(literal('same', { datatype: 'urn:b' })));
    assert.equal(key(literal('same', { language: 'en' })),
        key(literal('same', { language: 'EN', datatype: rdfLangString })));
    assert.equal(key(literal('same', { language: 'en', direction: 'ltr' })),
        key(literal('same', { language: 'EN', direction: 'ltr', datatype: rdfDirLangString })));
    assert.notEqual(key(literal('same', { language: 'en', direction: 'ltr' })),
        key(literal('same', { language: 'en', direction: 'rtl' })));
    assert.notEqual(key(literal('same', { language: 'en' })), key(literal('same', { language: 'fr' })));
    assert.equal(key(literal('same', { language: 'EN', datatype: 'http://www.w3.org/1999/02/22-rdf-syntax-ns#langString' })),
        key(literal('same', { language: 'en' })), 'language identity matches the Graph explorer normalization');
    assert.notEqual(key(blank('first')), key(blank('second')));
    assert.equal(key(blank('first', true)), key(blank('second', true)));
    assert.notEqual(api.termIdentity(blank('first', true), 'server/repository'),
        api.termIdentity(blank('first', true), 'another/repository'));
    assert.notEqual(key(triple(blank('first'))), key(triple(blank('second'))));
    assert.equal(key(triple(blank('first', true))), key(triple(blank('second', true))));
    assert.equal(api.hasUnverifiedBlankNode(triple(blank('first'))), true);
    assert.equal(api.hasUnverifiedBlankNode(triple(blank('first', true))), false);
});

test('worker identity index filters typed rows only against its initial baseline and releases its budget', async () => {
    const workers = [];
    const { api } = loadApi({ Worker: class extends IdentityWorker {
        constructor() { super(); workers.push(this); }
    } });
    const budget = api.createRowStoreBudget(1024 * 1024);
    const scope = 'server/repository';
    const iri = value => ({ kind: 'iri', value });
    const blank = { kind: 'bnode', value: 'stored', reference: true };
    const baseline = [
        [iri('urn:s'), blank, null],
        [iri('urn:other'), iri('urn:p'), { kind: 'literal', value: 'bonjour', language: 'fr' }]
    ];
    const index = await api.createRowIdentityIndex(scope, budget);
    await index.add(baseline);
    const retainedBytes = budget.usedBytes;
    assert.ok(retainedBytes > 0 && retainedBytes <= budget.maxBytes);

    const expanded = [
        [iri('urn:s'), { kind: 'bnode', value: 'stored', scope: 'ignored', reference: true }, null],
        [iri('urn:other'), iri('urn:p'), { kind: 'literal', value: 'bonjour', language: 'FR' }],
        [iri('urn:new'), iri('urn:p'), null]
    ];
    const first = await index.filter(expanded);
    const again = await index.filter([expanded[2]]);
    assert.deepEqual(Array.from(first, row => api.rowIdentity(row, scope)), [api.rowIdentity(expanded[2], scope)]);
    assert.deepEqual(Array.from(again, row => api.rowIdentity(row, scope)), [api.rowIdentity(expanded[2], scope)],
        'expanded rows are not added to the baseline');

    await index.dispose();
    assert.equal(budget.usedBytes, 0);
    assert.equal(workers[0].terminated, true);
});

test('identity sizing covers packed terms, escaped literals, and nested triple terms', async () => {
    const { api } = loadApi({ Worker: IdentityWorker });
    const budget = api.createRowStoreBudget(1024 * 1024);
    const index = await api.createRowIdentityIndex('server/repository', budget);
    const rows = [
        [{ kind: 'triple',
            subject: { kind: 'iri', value: 'urn:subject' },
            predicate: { kind: 'iri', value: 'urn:predicate' },
            object: { kind: 'literal', value: 'quote " slash \\ control \u0001 lone \ud800',
                language: 'EN', direction: 'ltr' } }],
        [[3, [1, 'stored', null, true], [0, 'urn:predicate'], [2, 'plain', 'http://www.w3.org/2001/XMLSchema#string']]],
        [[3, [0, 'urn:nested'], [0, 'urn:predicate'], [3, [1, 'response', 'batch-a'], [0, 'urn:p'], [2, 'line\nfeed', null, 'fr']]]]
    ];

    await index.add(rows);
    assert.equal(Array.from(await index.filter(rows)).length, 0,
        'the same nested typed rows resolve to their baseline keys');
    await index.dispose();
    assert.equal(budget.usedBytes, 0);
});

test('page response blank-node scope is fresh, including nodes nested in quoted triples', () => {
    const { api } = loadApi();
    const first = { kind: 'triple', subject: { kind: 'bnode', value: 'a', scope: 'from-server' },
        predicate: { kind: 'iri', value: 'urn:p' },
        object: { kind: 'triple', subject: { kind: 'bnode', value: 'certified', reference: true },
            predicate: { kind: 'iri', value: 'urn:p' }, object: { kind: 'bnode', value: 'b' } } };
    api.scopeUnverifiedBlankNodes(first, 'response-one');
    assert.equal(first.subject.scope, 'response-one');
    assert.equal(first.object.object.scope, 'response-one');
    assert.equal(first.object.subject.scope, undefined);

    const compactCertified = [1, 'stored', null, true];
    api.scopeUnverifiedBlankNodes(compactCertified, 'response-one');
    assert.deepEqual(compactCertified, [1, 'stored', null, true]);
});

test('query batch scoping leaves repository-certified compact blank nodes intact', async () => {
    const { api, document } = loadApi();
    const target = document.createElement('section');
    document.body.appendChild(target);
    const rows = [];
    const rowStore = {
        async append(batch) { rows.push(...batch); return rows.length; },
        async read(start, count) { return rows.slice(start, start + count); },
        async count() { return rows.length; },
        async dispose() { rows.length = 0; }
    };
    const renderer = new api.QueryResultRenderer(target, {
        batched: true, requestedLimit: 1, rowStore
    });
    renderer.beginBatch(0);
    await renderer.accept({ type: 'head', version: 2, 'term-encoding': 'array' });
    await renderer.accept({ type: 'view', id: 'tuple' });
    await renderer.accept({ type: 'vars', values: ['value'] });
    await renderer.accept({ type: 'metadata', values: { 'result-blank-node-scope': 'response-one' } });
    await renderer.accept({ type: 'rows', values: [[[1, 'stored', null, true]]] });

    assert.deepEqual(rows[0][0], [1, 'stored', null, true]);
    renderer.dispose();
});

function pageApp(realProtocol = false) {
    const output = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'rdf4j-page-scope-')), 'app.js');
    const source = path.resolve(__dirname, '../../../main/frontend/classic/workbenchApp.ts');
    const compilation = spawnSync('tsc', [...classicCompilerOptions(), '--target', 'ES2017',
        '--lib', 'ES2017,DOM', '--skipLibCheck', '--outFile', output, source], { encoding: 'utf8' });
    assert.equal(compilation.status, 0, compilation.stdout + compilation.stderr);
    const context = vm.createContext({ workbench: {}, window: {}, URL, Promise, setTimeout });
    vm.runInContext(fs.readFileSync(output, 'utf8'), context);
    const api = loadApi().api;
    api.createRowStore = async () => {
        const rows = [];
        return { append: async batch => { rows.push(...batch); }, count: async () => rows.length,
            read: async (start, count) => rows.slice(start, start + count), dispose: async () => {} };
    };
    if (!realProtocol) {
        api.consumeNdjsonResponse = async (response, options) => {
            for (const record of response.records) await options.onRecord(record);
            return { type: 'end' };
        };
    }
    context.workbench.queryStream = api;
    return { app: context.workbench.app, api };
}

test('page model ingestion assigns a different response scope to nested unverified nodes', async () => {
    const { app } = pageApp();
    const response = () => ({ ok: true, records: [{ type: 'view', id: 'explore' },
        { type: 'vars', values: ['value'] }, { type: 'rows', values: [[{ kind: 'triple',
            subject: { kind: 'bnode', value: 'same', scope: 'untrusted' }, predicate: { kind: 'iri', value: 'urn:p' },
            object: { kind: 'bnode', value: 'certified', reference: true } }]] }, { type: 'end' }] });
    const first = await app.loadModelFromResponse(response());
    const second = await app.loadModelFromResponse(response());
    const firstValue = (await first.rowStore.read(0, 1))[0][0];
    const secondValue = (await second.rowStore.read(0, 1))[0][0];
    assert.ok(firstValue.subject.scope);
    assert.notEqual(firstValue.subject.scope, 'untrusted');
    assert.notEqual(firstValue.subject.scope, secondValue.subject.scope);
    assert.equal(firstValue.object.scope, undefined);
});

test('page models can share a storage budget and filter batches before they are committed', async () => {
    const { app, api } = pageApp();
    const budget = api.createRowStoreBudget(1024 * 1024);
    const originalCreate = api.createRowStore;
    let receivedOptions;
    api.createRowStore = async options => { receivedOptions = options; return originalCreate(); };
    const response = { ok: true, records: [{ type: 'view', id: 'explore' }, { type: 'vars', values: ['value'] },
        { type: 'rows', values: [[{ kind: 'iri', value: 'urn:kept' }], [{ kind: 'iri', value: 'urn:duplicate' }]] },
        { type: 'end' }] };
    const model = await app.loadModel(async () => response, 'https://example.test/explore', undefined,
        { rowStoreOptions: { memoryBudget: budget }, filterRows: async rows => rows.slice(0, 1) });
    assert.equal(receivedOptions.memoryBudget, budget);
    assert.equal(model.rowCount, 1);
    assert.equal((await model.rowStore.read(0, 1))[0][0].value, 'urn:kept');
});

test('a page stream without a terminal end rejects and disposes its partial store', async () => {
    const { app, api } = pageApp();
    const originalCreate = api.createRowStore;
    let disposed = false;
    api.createRowStore = async options => {
        const store = await originalCreate(options);
        const originalDispose = store.dispose;
        store.dispose = async () => { disposed = true; return originalDispose(); };
        return store;
    };
    const response = { ok: true, records: [{ type: 'view', id: 'explore' }, { type: 'vars', values: ['value'] },
        { type: 'rows', values: [[{ kind: 'iri', value: 'urn:partial' }]] }] };
    await assert.rejects(app.loadModelFromResponse(response), /view and end are required/);
    assert.equal(disposed, true);
});

test('Explore page streams accept progress heartbeats before metadata and between row batches', async () => {
    const { app } = pageApp(true);
    const response = streamResponse([{ type: 'head', version: 1 }, { type: 'view', id: 'explore' },
        { type: 'vars', values: ['value'] },
        { type: 'progress', values: { 'explore-running': true } },
        { type: 'metadata', values: { 'explore-count': '42' } },
        { type: 'rows', values: [[{ kind: 'iri', value: 'urn:first' }]] },
        { type: 'progress', values: { 'explore-running': true } },
        { type: 'rows', values: [[{ kind: 'iri', value: 'urn:second' }]] }, { type: 'end' }]);
    const model = await app.loadModelFromResponse(response);
    assert.equal(model.metadata['explore-count'], '42');
    assert.equal(model.rowCount, 2);
});
